class Clock:
    def __init__(self, events):
        self.events, self.monotonic, self.wall = events, 100, 1_000_000
    def monotonic_ns(self):
        value = self.monotonic
        self.monotonic += 10
        self.events.append(['monotonic_ns', value])
        return value
    def time_ns(self):
        value = self.wall
        self.wall += 100
        self.events.append(['time_ns', value])
        return value


