        elif case == 'eval-context-owner':
            owner = self
            class Context:
                def capture_deadline(self, args, context):
                    owner.events.append(['capture_deadline', deepcopy(args['context'])])
                    return None, 10_000_000_000
                def remaining_captured(self, deadline):
                    owner.events.append(['remaining_captured', deadline])
                    return max(0, (deadline-owner.clock.time_ns())//1_000_000)
            self._native_context = Context()

    def _route(self, name, arguments):
        if self.image is None:
            # Exact original signatures include keyword-only connection.
            if name in ('_native', '_build_inputs', '_build_receipt', '_hia_adopt_native'):
                return REFERENCE[name](self, *arguments[:-1], _connection=arguments[-1])
            return REFERENCE[name](self, *arguments)
        frame = self.image.prepare(name, (self, *arguments), witness=self.witness)
        arguments = None
        return self.image.finish(frame)
    def _native(self, ref, context=None, *, _connection=None):
        return self._route('_native', (ref, context, _connection))
    def _build_inputs(self, ref, context, artifact, *, _connection=None):
        return self._route('_build_inputs', (ref, context, artifact, _connection))
    def _build_receipt(self, ref, context, artifact, *, _connection=None):
        return self._route('_build_receipt', (ref, context, artifact, _connection))
    def _cost_ledger(self, context, evaluation_wall_ns, native_wall_ns):
        return self._route('_cost_ledger', (context, evaluation_wall_ns, native_wall_ns))
    def _context(self, ref, *, _connection=None):
        self.events.append(['context', deepcopy(ref), _connection])
        return self.context
    def _program(self, ref, *, _connection=None):
        self.events.append(['program', deepcopy(ref), _connection])
        return self.programs[key(ref)]
    def _signature_values(self, program, exports=()):
        self.events.append(['signatures', program.label, exports])
        return self.signature
    def _required_claims(self, context, artifact, receipts, baseline, *, _connection=None):
        self.events.append(['required_claims', deepcopy(artifact), baseline, _connection])
        return self.objective
    def _lease(self, lease):
        self.events.append(['lease', lease])
        return {'id': 'lease', 'generation': '1', 'artifact': {'id': 'cand'}}
    def reference_batch(self, program, cases, **kwargs):
        self.events.append(['reference', program.label, deepcopy(cases), deepcopy(kwargs)])
        observations = [self.observation(case) for case in cases]
        if self.case == 'reference-difference' and program.label == 'cand':
            observations[0]['values'] = ['different']
        if self.case == 'reference-budget' and program.label == 'cand':
            return {'status': 'budget_exceeded', 'report': None}
        return {'status': 'returned', 'report': {'complete': True, 'observations': observations}}
    def observation(self, case):
        if case['arguments'][0] < 0:
            return {'status': 'trapped', 'trap_code': 'E_TEST', 'ledger': {'resources': {}}}
        return {'status': 'returned', 'values': [case['arguments'][0]], 'ledger': {'resources': {}}}
    def native_batch(self, data, signatures, cases, **kwargs):
        self.events.append(['native', data.hex(), deepcopy(cases), deepcopy(kwargs)])
        if self.case == 'invoke-budget':
            return {'status': 'budget_exceeded', 'termination_confirmed': True, 'captured_buffers': []}
        if kwargs.get('capture_buffers'):
            return {'status': 'returned', 'termination_confirmed': True, 'captured_buffers': [
                {'argument': 0, 'data': b'bytes', 'extent': '5'}] if self.case == 'invoke-buffers' else [],
                'report': {'observations': [{'status': 'returned', 'values': [cases[0]['arguments'][0]]}]}}
        if cases and cases[0]['arguments'][0] < 0:
            return {'status': 'trapped', 'returncode': -6, 'termination_confirmed': True}
        observations = [{'status': 'returned', 'values': [case['arguments'][0]], 'mismatch': False} for case in cases]
        return {'status': 'returned', 'termination_confirmed': True, 'returncode': 0,
                'report': {'completed_cases': len(cases), 'observations': observations, 'total_native_ns': '11'}}

    def invoke_case(self):
        if self.case.startswith('native-'):
            return self._native({'id': 'cand'}, {'id': 'ctx'})
        if self.case.startswith('build-'):
            return self._build_inputs({'id': 'build'}, {'id': 'ctx'}, {'id': 'cand'})
        if self.case.startswith('receipt-'):
            return self._build_receipt({'id': 'build'}, {'id': 'ctx'}, {'id': 'cand'})
        if self.case.startswith('cost-'):
            return self._cost_ledger(self.context, 99, 25)
        if self.case.startswith('adopt-'):
            return self._route('_hia_adopt_native', (self.args, None))
        if self.case.startswith('invoke-'):
            return self._route('invoke_lease', ('lease', 'f', [3]))
        return self._route('_hia_evaluate', (self.args,))


CASES = ('native-ok', 'native-installation', 'native-signature',
         'build-ok', 'build-object', 'build-receipt', 'receipt-ok',
         'cost-complete', 'cost-unknown', 'cost-truncated',
         'eval-ok', 'eval-context-owner', 'eval-latency-trap', 'reference-difference',
         'reference-budget', 'claim-error', 'publish-error',
         'adopt-ok', 'adopt-incomplete', 'adopt-net', 'adopt-abi',
         'invoke-ok', 'invoke-buffers', 'invoke-budget')


def normalize(value):
    if isinstance(value, Program):
        return ['program', value.label]
    if type(value) is bytes:
        return ['bytes', value.hex()]
    if type(value) in (list, tuple):
        return [normalize(item) for item in value]
    if type(value) is dict:
        return {name: normalize(item) for name, item in value.items()}
    return value


def fixture_call(case, image=None, witness=None):
    ports = Ports(case, image, witness)
    with ExitStack() as stack:
        stack.enter_context(patch.object(api, 'time', ports.clock))
        stack.enter_context(patch.object(api, 'validate', lambda *args, **kwargs: ports.events.append(['validate'])))
        stack.enter_context(patch.object(runner, 'run_reference_batch', ports.reference_batch))
        stack.enter_context(patch.object(runner, 'run_native_batch', ports.native_batch))
        stack.enter_context(patch.object(buffers, 'validate_cases', lambda *args: ports.events.append(['validate_cases'])))
        stack.enter_context(patch.object(buffers, 'validate_arguments', lambda *args: ports.events.append(['validate_arguments'])))
        try:
            result = ports.invoke_case()
            error = None
        except BaseException as caught:
            result = None
            error = {'type': type(caught).__name__, 'args': normalize(caught.args),
                     'code': getattr(caught, 'code', None), 'original_failure': caught is ports.failure}
        return {'value': normalize(result), 'error': error, 'events': normalize(ports.events),
                'publications': normalize(ports.store.published),
                'claim_complete': None if ports.claim is None else ports.claim.completed}


def loop_lifetime_observation(case, outer, image=None):
    """Run the exact original evaluation body with an observable for iterator.

    The replacement enumerate is a foreign provider shared by both routes.
    It records original break, continue, exhaustion and held-error release;
    no test policy replaces the nine emitted bodies.
    """
    def exercise():
        ports = Ports('reference-budget' if case == 'incomplete' else 'eval-ok', image)
        drops, references = [], []
        enumerate_original = enumerate
        def handled():
            error = sys.exception()
            return None if error is None else [type(error).__name__, list(error.args)]
        class ObservedIterator:
            def __init__(self, values):
                self.inner = enumerate_original(values)
                self.index = 0
                references.append(weakref.ref(self))
                ports.events.append(['iterator-created'])
            def __iter__(self):
                ports.events.append(['iterator-iter'])
                return self
            def __next__(self):
                ports.events.append(['iterator-next',self.index])
                if case == 'next-error' and self.index == 1:
                    raise ports.failure
                self.index += 1
                return next(self.inner)
            def __del__(self):
                event = ['iterator-del',handled()]
                drops.append(event)
                ports.events.append(event)
        original_native = ports.native_batch
        def native_batch(*args, **kwargs):
            if case == 'native-budget':
                ports.events.append(['controlled-native-budget'])
                return {'status':'budget_exceeded','returncode':-9,
                        'termination_confirmed':True,'report':None}
            return original_native(*args, **kwargs)
        def call():
            try:
                return {'value':ports.invoke_case(),'error':None}
            except BaseException as error:
                return {'value':None,'error':error}
        with ExitStack() as stack:
            stack.enter_context(patch.object(api,'time',ports.clock))
            stack.enter_context(patch.object(api,'enumerate',ObservedIterator,create=True))
            stack.enter_context(patch.object(api,'validate',lambda *a,**k:ports.events.append(['validate'])))
            stack.enter_context(patch.object(runner,'run_reference_batch',ports.reference_batch))
            stack.enter_context(patch.object(runner,'run_native_batch',native_batch))
            stack.enter_context(patch.object(buffers,'validate_cases',lambda *a:ports.events.append(['validate_cases'])))
            stack.enter_context(patch.object(buffers,'validate_arguments',lambda *a:ports.events.append(['validate_arguments'])))
            outcome = call()
        error_record = None if outcome['error'] is None else {
            'type':type(outcome['error']).__name__,'args':normalize(outcome['error'].args),
            'original_failure':outcome['error'] is ports.failure}
        result = normalize(outcome['value'])
        ports.failure = None
        before = {'alive':[ref() is not None for ref in references],
                  'drops':list(drops),'events':normalize(ports.events)}
        outcome.clear()
        after = {'alive':[ref() is not None for ref in references],
                 'drops':list(drops),'events':normalize(ports.events)}
        return {'value':result,'error':error_record,'before_release':before,
                'after_release':after,'publications':normalize(ports.store.published),
                'claim_complete':None if ports.claim is None else ports.claim.completed}
    if outer:
        try:
            raise LookupError('evaluation loop outer')
        except LookupError:
            return exercise()
    return exercise()

"""Exact Evaluation/import policies with held real IMPORT_FROM errors."""
from __future__ import annotations
import argparse
import builtins
from contextlib import ExitStack
from hashlib import sha256
import json
from pathlib import Path
import sys
from unittest.mock import patch
import weakref


def observe(fixtures, image, family, module_name, missing, outer):
    ports=fixtures.Ports('eval-ok' if family=='_hia_evaluate' else 'invoke-ok',image)
    provider=fixtures.runner if module_name=='hia_agent_runner' else fixtures.buffers
    events=[];weak=[];held=[]
    class Module:
        __name__='hepta.evaluation_import_proxy'
        __file__='/virtual/evaluation-import-proxy.py'
        def __init__(self):weak.append(weakref.ref(self))
        def __getattr__(self,name):
            events.append(['field',name])
            if name==missing:raise AttributeError(name)
            return getattr(provider,name)
        def __del__(self):
            active=sys.exception()
            events.append(['module-del',None if active is None else type(active).__name__])
    original_import=builtins.__import__
    def hooked(name,globals=None,locals=None,fromlist=(),level=0):
        if name==module_name and level==1:
            events.append(['import',list(fromlist)])
            return Module()
        return original_import(name,globals,locals,fromlist,level)
    def invoke():
        try:
            value=ports.invoke_case()
            return {'kind':'value','value':fixtures.normalize(value)}
        except BaseException as error:
            held.append(error)
            context=error.__context__
            return {'kind':'error','type':type(error).__name__,'args':fixtures.normalize(error.args),
                'name':getattr(error,'name',None),'path':getattr(error,'path',None),
                'context':None if context is None else [type(context).__name__,fixtures.normalize(context.args)],
                'suppress_context':error.__suppress_context__}
    def run():
        value=invoke()
        before={'alive':[ref() is not None for ref in weak],'events':list(events)}
        held.clear()
        return {'result':value,'while_error_held':before,
            'after_error_release':{'alive':[ref() is not None for ref in weak],'events':list(events)},
            'business':fixtures.normalize(ports.events),'publications':fixtures.normalize(ports.store.published)}
    with ExitStack() as stack:
        stack.enter_context(patch.object(fixtures.api,'time',ports.clock))
        stack.enter_context(patch.object(fixtures.api,'validate',lambda *args,**kwargs:ports.events.append(['validate'])))
        stack.enter_context(patch.object(fixtures.runner,'run_reference_batch',ports.reference_batch))
        stack.enter_context(patch.object(fixtures.runner,'run_native_batch',ports.native_batch))
        stack.enter_context(patch.object(fixtures.buffers,'validate_cases',lambda *args:ports.events.append(['validate_cases'])))
        stack.enter_context(patch.object(fixtures.buffers,'validate_arguments',lambda *args:ports.events.append(['validate_arguments'])))
        stack.enter_context(patch.object(builtins,'__import__',hooked))
        if outer:
            try:raise LookupError('outer')
            except LookupError:return run()
        return run()


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--source',type=Path,required=True)
    parser.add_argument('--manifest',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True)
    args=parser.parse_args()
    sys.path.insert(0,str(args.source.resolve()))
    from tests import hia_service_evaluation_fixtures as fixtures
    from hepta.hia_service_evaluation_native import NativeEvaluationImage
    manifest_raw=args.manifest.read_bytes();manifest=json.loads(manifest_raw)
    image_path=args.manifest.parent/manifest['image_path'];image_raw=image_path.read_bytes()
    assert sha256(image_raw).hexdigest()==manifest['image_sha256']
    files=('hepta/hia_service_evaluation_native.py','hepta/hia_service_evaluation_foreign.py',
        'tools/generate_hia_service_evaluation_foreign.py','tools/hia_service_evaluation_policy.py')
    before={name:sha256((args.source/name).read_bytes()).hexdigest() for name in files}
    image=NativeEvaluationImage(image_raw,manifest['image_sha256'])
    rows=[]
    groups=(('_hia_evaluate','hia_agent_runner',(None,'run_native_batch','run_reference_batch')),
        ('_hia_evaluate','hia_agent_buffers',(None,'validate_cases')),
        ('invoke_lease','hia_agent_runner',(None,'run_native_batch')),
        ('invoke_lease','hia_agent_buffers',(None,'validate_arguments')))
    for family,module,names in groups:
        for name in names:
            for outer in (False,True):
                reference=observe(fixtures,None,family,module,name,outer)
                start=image.entries
                actual=observe(fixtures,image,family,module,name,outer)
                rows.append({'family':family,'module':module,'missing':name,'outer':outer,
                    'reference':reference,'native':actual,'equal':reference==actual,
                    'actual_entries':image.entries-start})
    after={name:sha256((args.source/name).read_bytes()).hexdigest() for name in files}
    report={'schema':'hia.evaluation.import-module-retirement.v1','python':sys.version,
        'cases':len(rows),'equal':sum(row['equal'] for row in rows),'observations':rows,
        'image_sha256':manifest['image_sha256'],'source_before':before,'source_after':after,
        'inputs_unchanged':before==after and args.manifest.read_bytes()==manifest_raw and image_path.read_bytes()==image_raw,
        'whole_native':False,'current_cold':False,'garbage_collection_used':False}
    report['status']='PASS' if (report['equal']==report['cases'] and report['inputs_unchanged']
        and all(row['actual_entries']>0 for row in rows)) else 'FAIL'
    args.output.mkdir(mode=0o700)
    (args.output/'REPORT.json').write_text(json.dumps(report,sort_keys=True,indent=2)+'\n')
    print(json.dumps({k:report[k] for k in ('status','cases','equal','inputs_unchanged')}))
    return report['status']!='PASS'


if __name__=='__main__':raise SystemExit(main())

"""Generate complete Agent evaluation/adoption/lease HIA policy."""
from __future__ import annotations

import argparse
import ast
from pathlib import Path
import sys
import struct

ROOT = Path(__file__).resolve().parents[1]
if __package__ in (None, ''):
    sys.path.insert(0, str(ROOT))

from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions
from tools.generate_hia_machine_plan_control import (
    BODY as CONTROL_BODY, MAGIC, EMIT_MAGIC, ABI, OUTPUT)
from tools.generate_hia_core_lowering import emission, transport_helpers
from tools.hia_core_lowering_table import BODY as EXPAND_BODY, compress_table, reference_expand
from tools.hia_exception_delivery import BODY as EXCEPTION_BODY
from tools.hia_service_evaluation_control import compile_policy, OPS


def table(policy):
    starts = {}
    count = 0
    for function in policy.functions:
        starts[function.mode] = count + 1
        count += len(function.instructions)
    data = bytearray(64 + len(policy.functions) * 32)
    for function in policy.functions:
        metadata = len(data)
        data += bytes((int(i in function.temporary_slots) |
                       (2 * int(i in function.cell_slots)))
                      for i in range(function.next_slot))
        for own, outer in function.captures.values():
            data += struct.pack('<H', own.slot)
        info = (len(function.parameters) |
                (int(function.kind == 'generator') << 16) |
                (len(function.captures) << 32))
        struct.pack_into('<4Q', data, 64 + (function.mode - 1) * 32,
                         starts[function.mode], function.next_slot, info, metadata)
    offsets_at = len(data)
    data += b'\0' * (4 * count)
    ordinal = 0
    for function in policy.functions:
        shift = starts[function.mode] - 1
        for instruction in function.instructions:
            struct.pack_into('<I', data, offsets_at + ordinal * 4, len(data))
            ordinal += 1
            kind = instruction['kind']
            if kind == 'effect':
                destinations, arguments = instruction['destinations'], instruction['arguments']
                raw, vector = instruction['raw'], instruction['vector']
                consume = instruction['consume']
                handler = instruction['handler']
                data += struct.pack('<6BH I H', 1, instruction['opcode'], len(destinations),
                                    len(arguments), len(raw), len(consume), len(vector),
                                    handler + shift if handler else 0, 0)
                for ref in (*destinations, *arguments):
                    data += struct.pack('<H', ref.slot)
                for value in raw:
                    data += struct.pack('<I', value)
                for ref in (*vector, *consume):
                    data += struct.pack('<H', ref.slot)
            elif kind == 'jump':
                data += struct.pack('<BI', 2, instruction['target'] + shift)
            elif kind == 'flag':
                data += struct.pack('<BII', 3, instruction['yes'] + shift,
                                    instruction['no'] + shift)
            elif kind in ('return', 'yield'):
                data += struct.pack('<BH', 4 if kind == 'return' else 5,
                                    instruction['value'].slot)
            elif kind == 'error_return':
                data += b'\6'
            else:
                raise ValueError('unrendered instruction')
    literals_at = len(data)
    data += b'\0' * (4 * len(policy.literals))
    for index, value in enumerate(policy.literals):
        struct.pack_into('<I', data, literals_at + 4 * index, len(data))
        if value is None:
            kind, raw = 0, b''
        elif type(value) is bool:
            kind, raw = 1, bytes((int(value),))
        elif type(value) is int:
            kind, raw = 2, str(value).encode('ascii')
        elif type(value) is bytes:
            kind, raw = 5, value
        elif type(value) is float:
            kind, raw = 6, struct.pack('<d', value)
        elif type(value) is str:
            # CPython interns its ASCII name-character constants. Record that
            # representation in the immutable HIA-owned table, so the runtime
            # bridge does not infer a policy or change the object's identity.
            interned = all(c in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'
                           for c in value)
            kind, raw = (4 if interned else 3), value.encode('utf-8')
        else:
            raise ValueError('unrendered literal')
        data += struct.pack('<BQ', kind, len(raw)) + raw
    data += bytes((-len(data)) % 8)
    struct.pack_into('<8Q', data, 0, MAGIC, len(data), len(policy.functions), count,
                     64, offsets_at, literals_at, len(policy.literals))
    return bytes(data)


def program():
    return compile_policy((ROOT / 'tools/hia_service_evaluation_policy.py').read_text())


def source():
    policy = program()
    data = table(policy)
    packed = compress_table(data)
    if reference_expand(packed) != data:
        raise AssertionError('service-evaluation policy representation is not lossless')
    constants = {'MAGIC': MAGIC, 'EMIT_MAGIC': EMIT_MAGIC, 'ABI': ABI,
                 'OUTPUT_BYTES': OUTPUT, 'TABLE_BYTES': len(data),
                 'PACKED_BYTES': len(packed),
                 'WORKSPACE_BYTES': 1024 + 8 * max(fn.next_slot for fn in policy.functions),
                 **OPS}
    parsed = ast.parse(CONTROL_BODY + '\n' + transport_helpers() + '\n' +
                       emission(data, packed) + '\n' + EXPAND_BODY + '\n' + EXCEPTION_BODY)
    class Names(ast.NodeTransformer):
        def visit_Name(self, node):
            return ast.copy_location(ast.Constant(constants[node.id]), node) if node.id in constants else node
    return ast.fix_missing_locations(Names().visit(parsed))


def document():
    nodes = source().body
    names = {node.name: 'f' + str(index) for index, node in enumerate(nodes)}
    signatures = {node.name: ([arg.annotation.id for arg in node.args.args], node.returns.id)
                  for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = Builder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({'name': names[node.name], 'params': [builder.param(v) for v in builder.params],
            'returns': [builder.returns], 'effects': ['read', 'write', 'trap'],
            'entry': 'b0', 'blocks': builder.blocks})
    return compact_authoring_cfg({'schema': 'hepta.hia.program.v8',
                                  'module': 'service_evaluation', 'functions': functions})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path,
                        default=ROOT / 'examples/hia_bootstrap/service_evaluation.hiaasm')
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    raw = render_assembly(document()).encode()
    if args.check:
        if args.output.read_bytes() != raw:
            raise AssertionError('service-evaluation HIA differs from its complete policy')
    else:
        args.output.write_bytes(raw)
    print(args.output)


if __name__ == '__main__':
    main()

"""Complete nine-body service-evaluation continuation authoring.

Uses the reviewed Build lexical cell/named-function mechanism and the reviewed
Verification DICT_MERGE/DICT_UPDATE policy. The runtime receives no AST.
"""
from __future__ import annotations
import ast
import struct
from types import CodeType
from tools.hia_native_build_control import Compiler as BuildCompiler, Function as BuildFunction
from tools.hia_machine_plan_control import OPS, PACK, COMPARE

METHODS = ("_native", "_build_inputs", "_build_receipt", "_cost_ledger", "_hia_evaluate", "_hia_adopt_native", "invoke_lease")
HELPERS = ("_connection_arguments", "_value_observation")
ENTRIES = METHODS + HELPERS
DICT_UPDATE = 253
MAPPING_PREPARE = 254
MAPPING_CALL = 255


class Compiler(BuildCompiler):
    def __init__(self, source):
        self.source, self.tree = source, ast.parse(source)
        # None of the nine retained policies enters a context manager or an
        # exception region. A jump out of such a region requires its own
        # interpreter cleanup protocol; the local loop author must never
        # silently inherit a jump that bypasses __exit__ or CLEAR_HANDLED.
        if any(isinstance(node, (ast.With, ast.AsyncWith, ast.Try, ast.TryStar))
               for node in ast.walk(self.tree)):
            raise ValueError('evaluation policy has no reviewed context or exception region')
        self.lexical_codes = {}
        def remember(code):
            for child in code.co_consts:
                if isinstance(child, CodeType):
                    key = (child.co_firstlineno, child.co_name)
                    if key in self.lexical_codes:
                        raise ValueError('ambiguous evaluation lexical frame')
                    self.lexical_codes[key] = child
                    remember(child)
        remember(compile(source, '<evaluation-lexical-layout>', 'exec'))
        self.imports = {}
        for node in ast.walk(self.tree):
            if isinstance(node, ast.ImportFrom):
                if node.level != 1:
                    raise ValueError('evaluation import must be package-relative')
                self.imports.setdefault(node.module, set()).update(alias.name for alias in node.names)
        self.literals, self.literal_indices = [], {}
        self.functions, self.by_name = [], {}
        classes = [node for node in self.tree.body if isinstance(node, ast.ClassDef)]
        globals_ = [node for node in self.tree.body if isinstance(node, ast.FunctionDef)]
        if (len(classes) != 1 or classes[0].name != 'HIAAgentService'
                or tuple(getattr(node, 'name', None) for node in classes[0].body) != METHODS
                or tuple(node.name for node in globals_) != HELPERS):
            raise ValueError('complete evaluation policy inventory differs')
        for node in [*classes[0].body, *globals_]:
            if not isinstance(node, ast.FunctionDef) or node.decorator_list:
                raise ValueError('evaluation policy declaration differs')
            function = Function(self, node.name, node)
            self.functions.append(function)
            self.by_name[node.name] = function
        index = 0
        while index < len(self.functions):
            self.functions[index].compile()
            index += 1
        for mode, function in enumerate(self.functions, 1):
            function.mode = mode
        for function in self.functions:
            function.resolve()
        self._validate_calls()

    def literal(self, value):
        if type(value) is float:
            # Distinct IEEE payloads, especially +0 and -0, must not collapse
            # under Python's value equality. Each emitted index is boxed once.
            key = (float, struct.pack('<d', value))
            if key not in self.literal_indices:
                self.literal_indices[key] = len(self.literals)
                self.literals.append(value)
            return self.literal_indices[key]
        return super().literal(value)

    def nested(self, parent, node, kind):
        if kind not in ('function', 'generator', 'lambda'):
            raise ValueError('evaluation lexical child kind differs')
        function = Function(self, parent.name + ':' + kind + ':' + str(len(self.functions)),
                            node, parent=parent, kind=kind)
        self.functions.append(function)
        return function


class Function(BuildFunction):
    def expression(self, node):
        if isinstance(node, ast.BoolOp):
            result, done = self.slot(), self.label()
            for index, child in enumerate(node.values):
                self.store(result, self.expression(child))
                if index != len(node.values) - 1:
                    onward = self.label()
                    self.truth(self.copy(result),
                               onward if isinstance(node.op, ast.And) else done,
                               done if isinstance(node.op, ast.And) else onward)
                    self.mark(onward)
                    # JUMP_IF_*_OR_POP discards the first value before the
                    # next expression. Keep it only on the short-circuit edge,
                    # where the caller may truth-test that same object again.
                    self.release((result,))
            self.mark(done)
            return result
        if isinstance(node, ast.Call):
            if any(isinstance(arg, ast.Starred) for arg in node.args):
                raise ValueError('evaluation policy has no starred positional call')
            mappings = [i for i, keyword in enumerate(node.keywords) if keyword.arg is None]
            callee = self.expression(node.func)
            arguments = [self.expression(arg) for arg in node.args]
            if mappings:
                if mappings != [len(node.keywords)-1] or len(mappings) != 1:
                    raise ValueError('evaluation mapping must be the one final expansion')
                explicit = node.keywords[:-1]
                if tuple(k.arg for k in explicit) not in ((), ('kind',)):
                    raise ValueError('evaluation explicit mapping-keyword shape differs')
                # CALL_FUNCTION_EX constructs the positional tuple before
                # evaluating the keyword mapping. Its objects then outlive
                # the original operand temporaries under that same tuple.
                positional = self.effect('PACK', raw=(PACK['Tuple'],),
                                         vector=arguments, consume=reversed(arguments))
                values = [self.expression(k.value) for k in explicit]
                mapping = self.expression(node.keywords[-1].value)
                prepared = self.effect('CALL', (callee, positional, *values, mapping),
                    raw=(len(explicit), MAPPING_PREPARE),
                    consume=(*reversed(values), mapping))
                return self.effect('CALL', (callee, positional, prepared),
                                   raw=(0, MAPPING_CALL), consume=(callee, positional, prepared))
            keys = [self.compiler.literal(k.arg) for k in node.keywords]
            values = [self.expression(k.value) for k in node.keywords]
            if len(arguments) > 5 or len(keys) > 8:
                raise ValueError('evaluation fixed call extent differs')
            return self.effect('CALL', (callee, *arguments, *values),
                               raw=(len(arguments), len(keys), *keys),
                               consume=(callee, *arguments, *values))
        if isinstance(node, ast.Dict) and any(key is None for key in node.keys):
            result = self.effect('PACK', raw=(PACK['Dict'],), vector=())
            pending_keys, pending_values = [], []
            def flush():
                if pending_keys:
                    block = super(Function, self).expression(ast.Dict(
                        keys=list(pending_keys), values=list(pending_values)))
                    self.effect('CALL', (result, block), raw=(0, DICT_UPDATE),
                                destination=result, consume=(block,))
                    pending_keys.clear(); pending_values.clear()
            for key, value in zip(node.keys, node.values):
                if key is None:
                    flush()
                    mapping = self.expression(value)
                    self.effect('CALL', (result, mapping), raw=(0, DICT_UPDATE),
                                destination=result, consume=(mapping,))
                else:
                    if not isinstance(key, ast.Constant) or type(key.value) is not str:
                        raise ValueError('evaluation expanded dictionary key shape differs')
                    pending_keys.append(key); pending_values.append(value)
            flush()
            return result
        return super().expression(node)


    def statements(self, statements):
        for node in statements:
            if isinstance(node, ast.For):
                iterable = self.expression(node.iter)
                iterator = self.effect('ITER', (iterable,), consume=(iterable,))
                head, found, exhausted, broken, done = (self.label() for _ in range(5))
                self.mark(head)
                value = self.effect('NEXT', (iterator,))
                self.emit('flag', yes=found, no=exhausted)
                self.mark(found)
                self.assign(node.target, value)
                # Continue resumes the same iterator. Break owns only the
                # nearest loop exit; it retires that iterator before the
                # following statement and bypasses the normal else body.
                self.loop_stack.append((head, broken))
                self.statements(node.body)
                self.loop_stack.pop()
                self.jump(head)
                self.mark(exhausted)
                self.release((value, iterator))
                self.statements(node.orelse)
                self.jump(done)
                self.mark(broken)
                self.release((value, iterator))
                self.mark(done)
            elif isinstance(node, ast.Break):
                if not self.loop_stack:
                    raise ValueError('evaluation break has no owning loop')
                self.jump(self.loop_stack[-1][1])
            else:
                super().statements((node,))



def compile_policy(source):
    return Compiler(source)

